+		return thumbnail;
+	}
+
+	if (count_2d > 0) { // Is 2d scene
+		// NOTE -
+		// At the time of writing, CanvasItem nodes can't be rendered outside of the tree (see CanvasItem::queue_redraw() and RenderingServer::draw())
