+		thumbnail->set_image(thumbnail_image);
+
+		// Clean up
+		EditorNode::get_singleton()->call_deferred("remove_child", sub_viewport);
+		EditorNode::get_singleton()->call_deferred("remove_child", sub_viewport_gui);
