+void EditorPackedScenePreviewPlugin::_construct_scene_3d(Node *p_node, RID scenario, Vector<RID> &generated) const {
+	// Create visual instance into scenario
+	if (p_node->is_class("VisualInstance3D")) {
+		VisualInstance3D *v3d = Object::cast_to<VisualInstance3D>(p_node);
+		RS::get_singleton()->instance_set_scenario(v3d->get_instance(), scenario);
+		RS::get_singleton()->instance_set_transform(v3d->get_instance(), _get_global_transform_3d(v3d));
+	}
+
+	if (p_node->is_class("GridMap")) {
+		GridMap *gm = Object::cast_to<GridMap>(p_node);
+		Transform3D gm_t3d = _get_global_transform_3d(gm);
+		Array meshes = gm->get_meshes(); // get_bake_meshes() will return [Transform3D, Ref<Mesh>, Transform3D...], to get filled cell count do (array.size() / 2)
+		for (int i = 1; i <= meshes.size() / 2; i++) {
+			Ref<Mesh> mesh = meshes[i * 2 - 1];
+			Transform3D mesh_t3d = meshes[(i - 1) * 2]; // Is in local space
+			RID mesh_inst = RS::get_singleton()->instance_create();
+			RS::get_singleton()->instance_set_base(mesh_inst, mesh->get_rid());
+			RS::get_singleton()->instance_set_scenario(mesh_inst, scenario);
+			RS::get_singleton()->instance_set_transform(mesh_inst, gm_t3d * mesh_t3d);
+			generated.append(mesh_inst);
+		}
+	}
+
+	// Specific class settings
+	if (p_node->is_class("CPUParticles3D")) {
+		CPUParticles3D *cpu_particles = Object::cast_to<CPUParticles3D>(p_node);
+		RS::get_singleton()->instance_set_scenario(cpu_particles->get_instance(), scenario);
+		cpu_particles->set_pre_process_time(cpu_particles->get_lifetime() * 0.5); // Fast forward the particle emission to make it render something
+		cpu_particles->set_use_local_coordinates(true); // HACK - Now constructs scene outside of tree, using global coords will cause error, this may introduce visual bugs, but is the best solution now
+		cpu_particles->restart(true); // Keep seed to make simulation persistent
+	}
+
+	if (p_node->is_class("GPUParticles3D")) {
+		// Convert to CPUParticles (As GPUParticles can't be rendered correctly in thumbnails, don't know why)
+		GPUParticles3D *gpu_particles = Object::cast_to<GPUParticles3D>(p_node);
+		CPUParticles3D *cpu_particles = memnew(CPUParticles3D);
+		cpu_particles->convert_from_particles(gpu_particles);
+		gpu_particles->add_child(cpu_particles); // So the created CPUParticles instance will be freed later we call queue_free() on the preview scene
+
+		// Setup CPUParticles
+		RS::get_singleton()->instance_set_scenario(cpu_particles->get_instance(), scenario);
+		RS::get_singleton()->instance_set_transform(cpu_particles->get_instance(), _get_global_transform_3d(gpu_particles));
+		cpu_particles->set_pre_process_time(cpu_particles->get_lifetime() * 0.5);
+		cpu_particles->set_use_local_coordinates(true);
+		cpu_particles->restart(true);
+	}
+
+	for (int i = 0; i < p_node->get_child_count(); i++) {
+		_construct_scene_3d(p_node->get_child(i), scenario, generated);
+	}
+}
