+	bundle["conns"] = Array();
+	bundle["conn_count"] = Array();
+
+	// Recursively apply to all child scenes
+	for (int i = 0; i < edited_variants.size(); i++) {
+		if (Object::cast_to<PackedScene>(edited_variants[i])) {
+			_remove_scripts_from_packed_scene(edited_variants[i]);
